// Module resolution hooks for gen-mcp-adapter-fixtures.mjs.
//
// The pinned upstream (`external/pi-mcp-adapter` @ 3d953f90) is imported
// directly so fixtures are generated by the upstream implementation itself.
// Its submodule has no node_modules; three bare imports are remapped here:
//
// - `zod`                 -> chainable proxy stub (only touched by MCP-UI
//                            schema modules we never exercise)
// - `smol-toml`           -> throwing stub (TOML host-config import is P2)
// - `strip-json-comments` -> the REAL package, installed out-of-tree (see
//                            the generator's header comment); the JSONC
//                            fixtures depend on its exact semantics.
//
// Nothing is written into `external/` — the submodule stays pristine (G4).

const here = new URL(".", import.meta.url);

const STUBS = {
  zod: new URL("mcp-fixture-stub-zod.mjs", here).href,
  "smol-toml": new URL("mcp-fixture-stub-smol-toml.mjs", here).href,
};

// Set by the generator before `module.register()`.
const stripJsonCommentsUrl = process.env.RPI_MCP_FIXTURE_STRIP_JSON_COMMENTS_URL;
if (stripJsonCommentsUrl) {
  STUBS["strip-json-comments"] = stripJsonCommentsUrl;
}

export async function resolve(specifier, context, nextResolve) {
  const mapped = STUBS[specifier];
  if (mapped) {
    return { url: mapped, shortCircuit: true };
  }
  return nextResolve(specifier, context);
}
